missed.sql:
SELECT ROUND(100 * (1 - a / h), 1) AS missed_pct FROM (
  SELECT
    SUM(amount) FILTER (WHERE order_ts BETWEEN '2026-01-01' AND '2026-01-31') AS a,
    SUM(amount) FILTER (WHERE order_ts >= '2026-01-01' AND order_ts < '2026-02-01') AS h
  FROM orders WHERE status = 'completed'
);

table.sql:
SELECT day, sessions, conversions,
  ROUND(100.0 * conversions / sessions, 1) AS rate_pct
FROM daily ORDER BY day;

averaged.sql:
SELECT ROUND(AVG(100.0 * conversions / sessions), 1)
  AS avg_of_rates_pct
FROM daily;

pooled.sql:
SELECT ROUND(100.0 * SUM(conversions) / SUM(sessions), 1)
  AS overall_rate_pct
FROM daily;

