notIn.sql:
SELECT COUNT(*) AS never_ordered
FROM customers
WHERE customer_id NOT IN (SELECT customer_id FROM orders);

withoutNull.sql:
SELECT COUNT(*) AS never_ordered
FROM customers
WHERE customer_id NOT IN (
  SELECT customer_id FROM orders WHERE customer_id IS NOT NULL
);
